(1397370, 179294, 38011, '<td valign="top">Nice color and composition.</td>', 'Nice color and composition.', '2005-05-19 03:19:07.000000', NULL, 1),
(1397372, 179112, 38011, '<td valign="top">Don''t care for the split background in upper portion of shot, but otherwise very nicely done.</td>', 'Don''t care for the split background in upper portion of shot, but otherwise very nicely done.', '2005-05-19 03:20:48.000000', NULL, 1),
