(1397377, 179269, 23579, '<td valign="top">If you wanted to do this without getting the shadows, you could move the apple farther away from the background.</td>', 'If you wanted to do this without getting the shadows, you could move the apple farther away from the background.', '2005-05-19 03:22:12.000000', NULL, 1),
(1397379, 179285, 38011, '<td valign="top">just a snapshot, nothing extraordinary</td>', 'just a snapshot, nothing extraordinary', '2005-05-19 03:22:34.000000', NULL, 1),
(1397381, 178498, 23579, '<td valign="top">i would prefer to have more depth of field to make the woman''s face sharper.</td>', 'i would prefer to have more depth of field to make the woman''s face sharper.', '2005-05-19 03:23:50.000000', NULL, 1),
(1397383, 179263, 38011, '<td valign="top">Background too distracting, as well as red collar taking away from the apple and the arm is too blown out. Dog is cute.</td>', 'Background too distracting, as well as red collar taking away from the apple and the arm is too blown out. Dog is cute.', '2005-05-19 03:24:24.000000', NULL, 1),
