INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1399008, 178702, 37395, '<td valign="top">The back light is a bit strong. <br/>But its interesting.</td>', 'The back light is a bit strong. But its interesting.', '2005-05-19 18:01:49.000000', NULL, 1),
